function tx(p,t,size,role,w,weight){return H.text({parent:p,text:t,size:size||14,color:H.sw(APP,role||'ink'),w:w,weight:weight||5});}
function space(p,vertical){var f=H.frame({parent:p,name:'flex-space',w:1,h:1});f[vertical?'verticalSizing':'horizontalSizing']=sketch.FlexSizing.Fill;return f;}
function btn(p,t,id,kind,w){var b=row(p,'link:'+id,w,8,{left:12,right:12,top:0,bottom:0},kind==='primary'?'accent':kind==='danger'?'danger':'surface',36);b.style.corners.radii=[8,8,8,8];if(!kind)b.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];b.stackLayout.justifyContent=sketch.StackLayout.JustifyContent.Center;tx(b,t,13,kind?'inverse':'ink',undefined,6);H.order(b);return b;}
function ib(p,icon,id){var b=row(p,'link:'+id,32,0,0,null,32);b.stackLayout.justifyContent=sketch.StackLayout.JustifyContent.Center;H.icon({parent:b,d:H.paths[icon],size:18,color:H.hex(APP,'secondary')});H.order(b);return b;}
function card(p,n,w){var c=col(p,n,w,16,20,'surface');c.style.corners.radii=[12,12,12,12];c.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];return c;}
function composer(p,w){var c=card(p,'composer',w);tx(c,'Message…',15,'tertiary');var r=row(c,'composer-actions',w-40);ib(r,'plus','conversation--menu');btn(r,'Claude Sonnet 4.5  ⌄','settings-models');space(r);btn(r,'↑','conversation','primary',36);H.order(r);H.order(c);return c;}
