function signin(id,index){var s=H.screen({page:PAGE,platform:'macos',app:APP,id:id,w:1440,h:900,x:index*1560,y:0});s.stackLayout.justifyContent=sketch.StackLayout.JustifyContent.Center;s.stackLayout.alignItems=sketch.StackLayout.AlignItems.Center;var m=card(s,'auth-card',440);m.stackLayout.padding=32;m.stackLayout.gap=20;H.icon({parent:m,d:H.paths.sparkles,size:36,color:H.hex(APP,'accent')});tx(m,'Sign in to Weave',28,'ink',376,7);tx(m,'Continue with Apple, Google, or email.',14,'secondary',376);btn(m,'Continue with Apple','new-conversation',null,376);btn(m,'Continue with Google','new-conversation',null,376);var field=col(m,'email-field',376,8);tx(field,'Email',12,'secondary');var inp=row(field,'email-input',376,8,12,'canvas',44);inp.style.corners.radii=[8,8,8,8];inp.style.borders=[{color:H.sw(APP,'line'),thickness:1}];tx(inp,'you@example.com',14,'tertiary');H.order(inp);H.order(field);btn(m,'Continue','new-conversation','primary',376);tx(m,'We’ll email you a secure sign-in link.',12,'tertiary',376);return finish({s:s,m:m},id,index);}
function conversation(id,index){var z=shell(id,index,'conversation');title(z.m,'Move the billing webhook handler onto the new ledger client','conversation--menu');var columns=row(z.m,'thread-and-inspector',1200,0,0,null,820);columns.stackLayout.alignItems=sketch.StackLayout.AlignItems.Start;var thread=col(columns,'thread',880,20,32,null,820);var user=card(thread,'user-turn',816);tx(user,'YOU',11,'tertiary',undefined,6);tx(user,'Move the billing webhook handler onto the new ledger client. Keep the existing behavior and run the webhook tests.',15,'ink',776);H.order(user);var reasoning=row(thread,'link:conversation',816,8);H.icon({parent:reasoning,d:H.paths.brain,size:16,color:H.hex(APP,'secondary')});tx(reasoning,'Thought for 12 seconds',13,'secondary');tx(reasoning,'⌄',14,'secondary');H.order(reasoning);var tool=row(thread,'link:conversation--approval',816,10,12,'panel',48);H.icon({parent:tool,d:H.paths.terminal,size:16,color:H.hex(APP,'accent')});tx(tool,'terminal',13,'ink',undefined,6);tx(tool,'npm test — webhook',12,'secondary');space(tool);tx(tool,'Approval needed',12,'accent');H.order(tool);var answer=col(thread,'assistant-markdown',816,14);tx(answer,'Weave',14,'ink',undefined,7);tx(answer,'I’ve isolated the webhook changes. Here’s the plan:',15,'ink',816);tx(answer,'1. Replace the legacy client with the new ledger adapter.\n2. Preserve idempotency and signature verification.\n3. Run the webhook tests before preparing the release.',14,'ink',816);var code=card(answer,'code-block',816);code.stackLayout.gap=10;var cr=row(code,'code-toolbar',776);tx(cr,'TypeScript · services/billing/webhook.ts',11,'secondary');space(cr);ib(cr,'copy','conversation');H.order(cr);H.text({parent:code,text:'const ledger = createLedgerClient(config);\nawait ledger.webhooks.process(event, {\n  idempotencyKey: event.id,\n});',size:13,mono:true,color:H.sw(APP,'ink'),w:776});H.order(code);tx(answer,'I’ll ask before executing anything in your workspace.',14,'secondary',816);var acts=row(answer,'message-actions',816);ib(acts,'copy','conversation');ib(acts,'thumbsUp','conversation');ib(acts,'refresh','conversation');H.order(acts);H.order(answer);space(thread,true);composer(thread,816);H.order(thread);var inspect=col(columns,'context-inspector',320,24,24,'panel',820);var tabs=row(inspect,'inspector-tabs',272);btn(tabs,'Context','conversation');btn(tabs,'Files','artifacts');H.order(tabs);tx(inspect,'PROJECT',11,'tertiary',undefined,6);btn(inspect,'Personal  ↗','project',null,272);tx(inspect,'WORKSPACE',11,'tertiary',undefined,6);tx(inspect,'Workspace sprite\nConnected · macOS',13,'secondary',272);tx(inspect,'FILES IN CONTEXT',11,'tertiary',undefined,6);btn(inspect,'webhook.ts','artifacts',null,272);btn(inspect,'webhook.test.ts','artifacts',null,272);space(inspect,true);tx(inspect,'CONTEXT USAGE',11,'tertiary',undefined,6);var usage=row(inspect,'usage',272,14);var ring=H.icon({parent:usage,d:'<circle cx="12" cy="12" r="9" opacity=".15"/><path d="M12 3 A9 9 0 0 1 20.56 14.78"/>',size:52,color:H.hex(APP,'accent')});tx(usage,'30% used\n60k of 200k tokens',12,'secondary',190);H.order(usage);H.order(inspect);H.order(columns);return finish(z,id,index);}
function activity(id,index,work){var z=shell(id,index,'activity');title(z.m,'Activity');var rr=row(z.m,'work-layout',1200,0,0,null,820);rr.stackLayout.alignItems=sketch.StackLayout.AlignItems.Start;var list=col(rr,'activity-feed',work?880:1200,20,32,null,820);tx(list,'Work across your projects',14,'secondary');[['Prepare the release','RUNNING','Release checks · Verify the candidate · 1 / 3','Pending approval'],['Update the API documentation','COMPLETED','Personal · All 4 steps completed · 24 min ago','View result'],['Run integration checks','FAILED','Personal · Connection timed out · 1 hour ago','Review failure']].forEach((a,i)=>{var c=card(list,'link:activity--work',work?816:1136);tx(c,'● '+a[1],11,i===0?'accent':'secondary',undefined,7);var r=row(c,'work-title',work?776:1096,12);tx(r,a[0],19,'ink',undefined,7);space(r);btn(r,a[3],i===0?'conversation--approval':'activity--work',i===0?'primary':null);H.order(r);tx(c,a[2],12,'secondary');if(i===0){var progress=H.rect({parent:c,name:'plan-track',w:work?776:1096,h:4,fill:H.sw(APP,'line'),radius:2});var plan=row(c,'plan-status',work?776:1096);tx(plan,'✓ Inspect changes     → Run tests     ○ Publish summary',12,'secondary');space(plan);btn(plan,'Review','activity--work');H.order(plan);}H.order(c);});H.order(list);if(work){var ins=col(rr,'work-inspector',320,22,24,'panel',820);var hh=row(ins,'work-header',272);tx(hh,'Work details',16,'ink',undefined,7);space(hh);ib(hh,'x','activity');H.order(hh);tx(ins,'OBJECTIVE',11,'tertiary',undefined,6);tx(ins,'Prepare the release',22,'ink',272,7);tx(ins,'Verify the release candidate and prepare a concise summary of the changes.',14,'secondary',272);tx(ins,'ATTEMPT 1 · RUNNING',11,'accent',272,7);tx(ins,'Workspace sprite\nStarted 3 minutes ago',13,'secondary',272);tx(ins,'PLAN · 1 OF 3 COMPLETE',11,'tertiary',272,6);tx(ins,'✓  Inspect the candidate\n\n→  Run the webhook tests\n\n○  Publish the release summary',14,'ink',272);var notice=card(ins,'pending-approval',272);tx(notice,'Approval needed',14,'ink',232,7);tx(notice,'Run npm test in the project workspace',13,'secondary',232);btn(notice,'Respond','conversation--approval','primary',232);H.order(notice);space(ins,true);var actions=row(ins,'work-actions',272);btn(actions,'Steer','conversation',null,130);btn(actions,'Cancel','activity',null,130);H.order(actions);H.order(ins);}H.order(rr);return finish(z,id,index);}
function overlay(s){s.stackLayout=null;H.rect({parent:s,name:'link:back',w:1440,h:900,fill:H.alpha(H.hex(APP,'ink'),.4)});}
function hotspot(p,id,x,y,w,h){var f=H.frame({parent:p,name:'link:'+id,w:w,h:h});f.stackLayout=null;f.frame.x=x;f.frame.y=y;return f;}
function approval(id,index){var s=conversation(id,index);overlay(s);var c=card(s,'approval-dialog',520);c.frame.x=460;c.frame.y=295;c.stackLayout.gap=20;c.stackLayout.padding=28;H.icon({parent:c,d:H.paths.shield,size:28,color:H.hex(APP,'accent')});tx(c,'Approval required',12,'accent',464,7);tx(c,'Run npm test in the project workspace',23,'ink',464,7);tx(c,'Weave is requesting permission to execute this command. Review it before continuing.',14,'secondary',464);var cmd=row(c,'command',464,8,12,'panel',44);H.text({parent:cmd,text:'npm test',mono:true,size:13,color:H.sw(APP,'ink')});H.order(cmd);var r=row(c,'actions',464,8);btn(r,'Deny','back',null,100);space(r);btn(r,'Always','conversation',null,112);btn(r,'Allow once','conversation','primary',132);H.order(r);H.order(c);c.frame.x=460;c.frame.y=265;return s;}
function menu(id,index){var s=conversation(id,index);overlay(s);var m=H.inst('Menu/'+APP+'/default',s);m.frame.x=1164;m.frame.y=70;[[29,'conversation'],[69,'conversation'],[109,'project'],[166,'artifacts'],[206,'conversation--delete']].forEach(a=>hotspot(s,a[1],1170,70+a[0],232,32));return s;}
function deletion(id,index){var s=conversation(id,index);overlay(s);var m=H.inst('Dialog/'+APP+'/destructive',s);m.overrides.filter(o=>o.property==='stringValue').forEach(o=>{if(o.value==='Delete this project?')o.value='Delete this conversation?';if(String(o.value).indexOf('This action cannot')===0)o.value='This action cannot be undone. This conversation and its messages will be removed.';});m.frame.x=540;m.frame.y=365;var c=m.detach();function nameButtons(l){if(l.type==='Text'&&l.text==='Cancel')l.parent.name='link:back';if(l.type==='Text'&&l.text==='Delete')l.parent.name='link:new-conversation';(l.layers||[]).forEach(nameButtons);}nameButtons(c);return s;}
function search(id,index){var s=home(id,index);overlay(s);var i=H.inst('CommandPalette/'+APP+'/default',s);var c=i.detach();c.layers.slice().forEach(l=>l.remove());c.name='CommandPalette/ledger';c.stackLayout={direction:sketch.StackLayout.Direction.Column,gap:8,padding:12,alignItems:sketch.StackLayout.AlignItems.Start};c.verticalSizing=sketch.FlexSizing.Hug;c.frame.width=620;var query=row(c,'query',596,12,12,null,48);H.icon({parent:query,d:H.paths.search,size:20,color:H.hex(APP,'secondary')});tx(query,'ledger',17,'ink');space(query);btn(query,'esc','back');H.order(query);[['Projects','Ledger migration','project','⌘1'],['Conversations','Move the billing webhook handler onto the new ledger client','conversation','↵'],['Work','Prepare the release · Verify ledger candidate','activity--work','⌘3']].forEach(a=>{tx(c,a[0],11,'tertiary',596,6);var r=row(c,'link:'+a[2],596,12,12,a[2]==='conversation'?'hover':null,52);tx(r,a[1],13,'ink',508,6);tx(r,a[3],12,'secondary');H.order(r);});var hints=row(c,'hints',596,16,12);tx(hints,'↑↓ Navigate     ↵ Open',12,'secondary');space(hints);btn(hints,'Close','back');H.order(hints);H.order(c);c.frame.x=410;c.frame.y=205;return s;}

function normalizeLinks(s){function walk(l){if(/^link:.* \d+$/.test(l.name))l.name=l.name.replace(/ \d+$/,'');(l.layers||[]).forEach(walk);}walk(s);}
